// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address x, address y) public {
        vm.assume(x != y);

        // Step 1: actor attempts to transfer ownership to x.
        vm.prank(actor);
        bool firstOk;
        try c.transferOwnership(x) { firstOk = true; } catch { firstOk = false; }

        // Step 2: the same actor attempts another transfer to y.
        vm.prank(actor);
        bool secondOk;
        try c.transferOwnership(y) { secondOk = true; } catch { secondOk = false; }

        // General rule: control is exclusive. A caller may only chain a second
        // ownership transfer if they are still the owner, i.e. if their first
        // transfer succeeded AND targeted themselves. Otherwise the second call
        // must have reverted.
        assertTrue(!(firstOk && x != actor && secondOk));
    }
}
